// Embeds drizzle/*.sql into src/db/migrations.generated.ts so they ship inside the serverless bundle.
import fs from "node:fs"; import path from "node:path";
const dir = path.resolve("drizzle");
const files = fs.readdirSync(dir).filter((f) => f.endsWith(".sql")).sort();
const list = files.map((f) => ({ name: f, sql: fs.readFileSync(path.join(dir, f), "utf8") }));
fs.writeFileSync("src/db/migrations.generated.ts",
  "// AUTO-GENERATED by scripts/embed-migrations.mjs — do not edit.\nexport const MIGRATIONS: { name: string; sql: string }[] = " + JSON.stringify(list, null, 2) + ";\n");
console.log("embedded", files.length, "migrations");
